import{_ as l,o as E,c as e,a2 as _}from"./chunks/framework.BZO4qERu.js";const a=JSON.parse('{"title":"按键 (Keys)","description":"","frontmatter":{},"headers":[],"relativePath":"keys.md","filePath":"keys.md","lastUpdated":1669882888000}'),o={name:"keys.md"};function t(C,i,O,D,K,Y){return E(),e("div",null,[...i[0]||(i[0]=[_('<h1 id="按键-keys" tabindex="-1">按键 (Keys)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>按键模拟部分提供了一些模拟物理按键的全局函数, 包括Home、音量键、照相键等, 有的函数依赖于无障碍服务, 有的函数依赖于root权限.</p><p>一般来说, 以大写字母开头的函数都依赖于root权限. 执行此类函数时, 如果没有root权限, 则函数执行后没有效果, 并会在控制台输出一个警告.</p><h2 id="back" tabindex="-1">back()</h2><ul><li>返回 {boolean}</li></ul><p>模拟按下返回键. 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="home" tabindex="-1">home()</h2><ul><li>返回 {boolean}</li></ul><p>模拟按下Home键. 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="powerdialog" tabindex="-1">powerDialog()</h2><ul><li>返回 {boolean}</li></ul><p>弹出电源键菜单. 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="notifications" tabindex="-1">notifications()</h2><ul><li>返回 {boolean}</li></ul><p>拉出通知栏. 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="quicksettings" tabindex="-1">quickSettings()</h2><ul><li>返回 {boolean}</li></ul><p>显示快速设置(下拉通知栏到底). 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="recents" tabindex="-1">recents()</h2><ul><li>返回 {boolean}</li></ul><p>显示最近任务. 返回是否执行成功. 此函数依赖于无障碍服务.</p><h2 id="splitscreen" tabindex="-1">splitScreen()</h2><ul><li>返回 {boolean}</li></ul><p>分屏. 返回是否执行成功. 此函数依赖于无障碍服务, 并且需要系统自身功能的支持.</p><h2 id="home-1" tabindex="-1">Home()</h2><p>模拟按下Home键. 此函数依赖于root权限.</p><h2 id="back-1" tabindex="-1">Back()</h2><p>模拟按下返回键. 此函数依赖于root权限.</p><h2 id="power" tabindex="-1">Power()</h2><p>模拟按下电源键. 此函数依赖于root权限.</p><h2 id="menu" tabindex="-1">Menu()</h2><p>模拟按下菜单键. 此函数依赖于root权限.</p><h2 id="volumeup" tabindex="-1">VolumeUp()</h2><p>按下音量上键. 此函数依赖于root权限.</p><h2 id="volumedown" tabindex="-1">VolumeDown()</h2><p>按键音量上键. 此函数依赖于root权限.</p><h2 id="camera" tabindex="-1">Camera()</h2><p>模拟按下照相键.</p><h2 id="up" tabindex="-1">Up()</h2><p>模拟按下物理按键上. 此函数依赖于root权限.</p><h2 id="down" tabindex="-1">Down()</h2><p>模拟按下物理按键下. 此函数依赖于root权限.</p><h2 id="left" tabindex="-1">Left()</h2><p>模拟按下物理按键左. 此函数依赖于root权限.</p><h2 id="right" tabindex="-1">Right()</h2><p>模拟按下物理按键右. 此函数依赖于root权限.</p><h2 id="ok" tabindex="-1">OK()</h2><p>模拟按下物理按键确定. 此函数依赖于root权限.</p><h2 id="text-text" tabindex="-1">Text(text)</h2><ul><li>text {string} 要输入的文字, 只能为英文或英文符号 输入文字text. 例如<code>Text(&quot;aaa&quot;);</code></li></ul><h2 id="keycode-code" tabindex="-1">KeyCode(code)</h2><ul><li>code {number} | &lt;String&gt; 要按下的按键的数字代码或名称. 参见下表. 模拟物理按键. 例如<code>KeyCode(29)</code>和<code>KeyCode(&quot;KEYCODE_A&quot;)</code>是按下A键.</li></ul><h1 id="附录-keycode对照表" tabindex="-1">附录: KeyCode对照表</h1><p>KeyCode KeyEvent Value</p><ul><li>KEYCODE_MENU 1</li><li>KEYCODE_SOFT_RIGHT 2</li><li>KEYCODE_HOME 3</li><li>KEYCODE_BACK 4</li><li>KEYCODE_CALL 5</li><li>KEYCODE_ENDCALL 6</li><li>KEYCODE_0 7</li><li>KEYCODE_1 8</li><li>KEYCODE_2 9</li><li>KEYCODE_3 10</li><li>KEYCODE_4 11</li><li>KEYCODE_5 12</li><li>KEYCODE_6 13</li><li>KEYCODE_7 14</li><li>KEYCODE_8 15</li><li>KEYCODE_9 16</li><li>KEYCODE_STAR 17</li><li>KEYCODE_POUND 18</li><li>KEYCODE_DPAD_UP 19</li><li>KEYCODE_DPAD_DOWN 20</li><li>KEYCODE_DPAD_LEFT 21</li><li>KEYCODE_DPAD_RIGHT 22</li><li>KEYCODE_DPAD_CENTER 23</li><li>KEYCODE_VOLUME_UP 24</li><li>KEYCODE_VOLUME_DOWN 25</li><li>KEYCODE_POWER 26</li><li>KEYCODE_CAMERA 27</li><li>KEYCODE_CLEAR 28</li><li>KEYCODE_A 29</li><li>KEYCODE_B 30</li><li>KEYCODE_C 31</li><li>KEYCODE_D 32</li><li>KEYCODE_E 33</li><li>KEYCODE_F 34</li><li>KEYCODE_G 35</li><li>KEYCODE_H 36</li><li>KEYCODE_I 37</li><li>KEYCODE_J 38</li><li>KEYCODE_K 39</li><li>KEYCODE_L 40</li><li>KEYCODE_M 41</li><li>KEYCODE_N 42</li><li>KEYCODE_O 43</li><li>KEYCODE_P 44</li><li>KEYCODE_Q 45</li><li>KEYCODE_R 46</li><li>KEYCODE_S 47</li><li>KEYCODE_T 48</li><li>KEYCODE_U 49</li><li>KEYCODE_V 50</li><li>KEYCODE_W 51</li><li>KEYCODE_X 52</li><li>KEYCODE_Y 53</li><li>KEYCODE_Z 54</li><li>KEYCODE_COMMA 55</li><li>KEYCODE_PERIOD 56</li><li>KEYCODE_ALT_LEFT 57</li><li>KEYCODE_ALT_RIGHT 58</li><li>KEYCODE_SHIFT_LEFT 59</li><li>KEYCODE_SHIFT_RIGHT 60</li><li>KEYCODE_TAB 61</li><li>KEYCODE_SPACE 62</li><li>KEYCODE_SYM 63</li><li>KEYCODE_EXPLORER 64</li><li>KEYCODE_ENVELOPE 65</li><li>KEYCODE_ENTER 66</li><li>KEYCODE_DEL 67</li><li>KEYCODE_GRAVE 68</li><li>KEYCODE_MINUS 69</li><li>KEYCODE_EQUALS 70</li><li>KEYCODE_LEFT_BRACKET 71</li><li>KEYCODE_RIGHT_BRACKET 72</li><li>KEYCODE_BACKSLASH 73</li><li>KEYCODE_SEMICOLON 74</li><li>KEYCODE_APOSTROPHE 75</li><li>KEYCODE_SLASH 76</li><li>KEYCODE_AT 77</li><li>KEYCODE_NUM 78</li><li>KEYCODE_HEADSETHOOK 79</li><li>KEYCODE_FOCUS 80</li><li>KEYCODE_PLUS 81</li><li>KEYCODE_MENU 82</li><li>KEYCODE_NOTIFICATION 83</li><li>KEYCODE_SEARCH 84</li><li>TAG_LAST_ KEYCODE 85</li></ul>',59)])])}const n=l(o,[["render",t]]);export{a as __pageData,n as default};
